<?php if ($tracking_completed && $tracking_documents): ?><h2>Dokumen SKHP</h2><div class="public-track-documents"><?php foreach ($tracking_documents as $doc): ?><form method="post" action="<?= site_url('lacak-status/skhp/'.$doc->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="hidden" name="booking_code" value="<?= e($tracking->booking_code) ?>"><button class="button primary" type="submit">Unduh <?= e($doc->original_name) ?></button></form><?php endforeach; ?></div><?php endif; ?></div><?php endif; ?>
